BikeCatalog.ById = {}
for _, bike in ipairs(BikeCatalog.Bikes) do
	BikeCatalog.ById[bike.Id] = bike
end

function BikeCatalog.Get(id)
	return BikeCatalog.ById[id]
end

-- Bikes of one tier, or of one base model, in catalog (price) order.
function BikeCatalog.Filter(field, value)
	local out = {}
	for _, bike in ipairs(BikeCatalog.Bikes) do
		if bike[field] == value then
			table.insert(out, bike)
		end
	end
	return out
end

-- Clones the bike's base model from bikesFolder, names it after the catalog bike, applies its
-- skin (once TextureId is filled in) and rigs it. Returns the unparented model.
function BikeCatalog.Spawn(id, bikesFolder)
	local bike = BikeCatalog.ById[id]
	if not bike then
		error(("BikeCatalog: unknown bike %q"):format(tostring(id)), 2)
	end
	local template = bikesFolder:FindFirstChild(bike.Base)
	if not template then
		error(("BikeCatalog: %s has no base model %q"):format(bikesFolder:GetFullName(), bike.Base), 2)
	end
	local MotorcycleRig = require(script.Parent.MotorcycleRig)
	local model = template:Clone()
	model:SetAttribute("BikeId", bike.Id)
	model:SetAttribute("SteeringRake", MotorcycleRig.RAKE_BY_MODEL[bike.Base])
	model.Name = bike.Name
	if bike.TextureId ~= "" then
		MotorcycleRig.SetSkin(model, bike.TextureId)
	end
	if bike.NeonColor then -- electric bikes: glowing light strips
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("MeshPart") and part.Name == "LightStrips" then
				pcall(function()
					part.TextureID = ""
				end)
				part.Material = Enum.Material.Neon
				part.Color = bike.NeonColor
			end
		end
	end
	MotorcycleRig.Rig(model)
	return model
end

return BikeCatalog
